#!/usr/bin/env node
// P0 Step 5C.9A — provider-free MP4 validation + bounded download/import tests.
// Uses only generated bytes and a disposable 127.0.0.1 server. No browser,
// provider profile, provider endpoint, Python, PostgreSQL, or quota.

import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { Readable } from "node:stream";
import { generateId } from "../lib/protocol/ids.mjs";
import {
  inspectMp4File,
  MP4_DEFAULT_LIMITS,
  MP4_ERRORS,
  normalizeMp4Limits,
  validateMp4Bytes
} from "../lib/worker/media/mp4-validator.mjs";
import {
  createExactOriginPolicy,
  downloadAndImportVideo,
  VIDEO_IMPORT_DEFAULTS,
  VIDEO_IMPORT_ERRORS
} from "../lib/worker/media/video-download-import.mjs";
import { createFakeProviderServer, makeSyntheticMp4 } from "./helpers/step5c9-fake-provider-server.mjs";

let passed = 0;
let failed = 0;
function check(name, actual, expected = true) {
  try {
    assert.deepEqual(actual, expected);
    passed += 1;
  } catch (err) {
    failed += 1;
    console.error(`FAIL ${name}\n  actual:   ${JSON.stringify(actual)}\n  expected: ${JSON.stringify(expected)}`);
  }
}
async function throwsCode(name, fn, code) {
  try {
    await fn();
    failed += 1;
    console.error(`FAIL ${name} (expected ${code})`);
  } catch (err) {
    check(name, err?.code, code);
  }
}

const roots = [];
function root(tag) {
  const value = mkdtempSync(path.join(os.tmpdir(), `avc-5c9-media-${tag}-`));
  roots.push(value);
  return value;
}
function cleanupRoots() {
  const tempRoot = path.resolve(os.tmpdir());
  while (roots.length) {
    const item = roots.pop();
    const resolved = path.resolve(item);
    if (path.dirname(resolved) !== tempRoot || !path.basename(resolved).startsWith("avc-5c9-media-")) continue;
    try { rmSync(resolved, { recursive: true, force: true }); } catch { /* best effort */ }
  }
}
process.once("exit", cleanupRoots);
function listParts(dir) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { recursive: true }).map(String).filter((name) => name.includes(".part-"));
}

const valid = makeSyntheticMp4();
const extended = makeSyntheticMp4({ extendedMdat: true });
const toEnd = makeSyntheticMp4({ mdatToEnd: true });

// ---- validator defaults/configuration ----
check("default minimum is 32 KiB", MP4_DEFAULT_LIMITS.minBytes, 32 * 1024);
check("default maximum is 512 MiB", MP4_DEFAULT_LIMITS.maxBytes, 512 * 1024 * 1024);
check("default download timeout is five minutes", VIDEO_IMPORT_DEFAULTS.timeoutMs, 5 * 60 * 1000);
check("limits normalize", normalizeMp4Limits({ minBytes: 4096, maxBytes: 65536 }), { minBytes: 4096, maxBytes: 65536 });
await throwsCode("minimum below safety floor rejected", async () => normalizeMp4Limits({ minBytes: 10 }), MP4_ERRORS.E_MEDIA_CONFIG);
await throwsCode("maximum above hard cap rejected", async () => normalizeMp4Limits({ maxBytes: MP4_DEFAULT_LIMITS.maxBytes + 1 }), MP4_ERRORS.E_MEDIA_CONFIG);
await throwsCode("maximum below minimum rejected", async () => normalizeMp4Limits({ minBytes: 65536, maxBytes: 32768 }), MP4_ERRORS.E_MEDIA_CONFIG);

// ---- bounded structural MP4 validation ----
const inspected = await validateMp4Bytes(valid);
check("valid MP4 mime", inspected.mimeType, "video/mp4");
check("valid MP4 size", inspected.sizeBytes, valid.length);
check("valid MP4 major brand", inspected.majorBrand, "isom");
check("valid MP4 requires movie box", inspected.hasMovieBox, true);
check("valid MP4 requires media-data box", inspected.hasMediaData, true);
check("extended-size box accepted", (await validateMp4Bytes(extended)).hasMediaData, true);
check("terminal size-zero box accepted", (await validateMp4Bytes(toEnd)).hasMediaData, true);

await throwsCode("HTML rejected", async () => validateMp4Bytes(Buffer.concat([Buffer.from("<!doctype html>"), Buffer.alloc(40 * 1024)])), MP4_ERRORS.E_MEDIA_INVALID);
await throwsCode("JSON rejected", async () => validateMp4Bytes(Buffer.concat([Buffer.from("{\"ok\":false}"), Buffer.alloc(40 * 1024)])), MP4_ERRORS.E_MEDIA_INVALID);
await throwsCode("undersized media rejected", async () => validateMp4Bytes(valid.subarray(0, 1000)), MP4_ERRORS.E_MEDIA_TOO_SMALL);
await throwsCode("configured oversize media rejected", async () => validateMp4Bytes(valid, { minBytes: 1024, maxBytes: 8192 }), MP4_ERRORS.E_MEDIA_TOO_LARGE);

const badLength = Buffer.from(valid);
badLength.writeUInt32BE(0x7fffffff, 0);
await throwsCode("box beyond EOF rejected", async () => validateMp4Bytes(badLength), MP4_ERRORS.E_MEDIA_INVALID);
const noFtyp = Buffer.from(valid); noFtyp.write("free", 4, 4, "ascii");
await throwsCode("missing ftyp rejected", async () => validateMp4Bytes(noFtyp), MP4_ERRORS.E_MEDIA_INVALID);
const noMoov = Buffer.from(valid); noMoov.write("free", 28, 4, "ascii");
await throwsCode("missing moov rejected", async () => validateMp4Bytes(noMoov), MP4_ERRORS.E_MEDIA_INVALID);
const mdatOffset = valid.indexOf(Buffer.from("mdat", "ascii"));
const noMdat = Buffer.from(valid); noMdat.write("free", mdatOffset, 4, "ascii");
await throwsCode("missing mdat rejected", async () => validateMp4Bytes(noMdat), MP4_ERRORS.E_MEDIA_INVALID);
const emptyMdat = Buffer.from(valid); emptyMdat.writeUInt32BE(8, mdatOffset - 4);
await throwsCode("empty mdat rejected", async () => validateMp4Bytes(emptyMdat), MP4_ERRORS.E_MEDIA_INVALID);
const invalidType = Buffer.from(valid); invalidType[4] = 0;
await throwsCode("non-printable box type rejected", async () => validateMp4Bytes(invalidType), MP4_ERRORS.E_MEDIA_INVALID);

const fileRoot = root("inspect");
const file = path.join(fileRoot, "owned.mp4");
writeFileSync(file, valid);
check("file inspector reads bounded structure", (await inspectMp4File(file)).boxCount >= 3, true);
let missingFileError;
try { await inspectMp4File(path.join(fileRoot, "secret-name.mp4")); } catch (err) { missingFileError = err; }
check("missing file rejected", missingFileError?.code, MP4_ERRORS.E_MEDIA_INVALID);
check("missing file error is sanitized", /secret-name|[A-Za-z]:\\|\/tmp\//.test(missingFileError?.message || ""), false);

// ---- exact-origin policy ----
const fake = await createFakeProviderServer();
const policy = createExactOriginPolicy({ allowedOrigins: [fake.origin], allowHttpLoopback: true });
check("policy accepts exact loopback origin", policy.assertAllowed(fake.url("/video")).origin, fake.origin);
await throwsCode("policy rejects credentials in URL", async () => policy.assertAllowed(fake.url("/video").replace("http://", "http://user:pass@")), VIDEO_IMPORT_ERRORS.E_MEDIA_SOURCE_REJECTED);
await throwsCode("policy rejects another hostname", async () => policy.assertAllowed(fake.url("/video").replace("127.0.0.1", "localhost")), VIDEO_IMPORT_ERRORS.E_MEDIA_SOURCE_REJECTED);
await throwsCode("HTTP origin requires explicit loopback opt-in", async () => createExactOriginPolicy({ allowedOrigins: [fake.origin] }), VIDEO_IMPORT_ERRORS.E_MEDIA_CONFIG);
check("HTTPS origin is accepted without test opt-in", createExactOriginPolicy({ allowedOrigins: ["https://media.invalid"] }).assertAllowed("https://media.invalid/video").origin, "https://media.invalid");

async function download(pathname, tag, overrides = {}) {
  return downloadAndImportVideo({
    source: fake.url(pathname),
    outputRoot: root(tag),
    relativeDirectory: "media/generated",
    generationAttemptId: generateId("attempt"),
    originPolicy: policy,
    ...overrides
  });
}

// ---- successful bounded imports ----
const successRoot = root("success");
const success = await downloadAndImportVideo({
  source: fake.url("/video?signature=must-not-leak"),
  outputRoot: successRoot,
  relativeDirectory: "media/generated",
  generationAttemptId: generateId("attempt"),
  originPolicy: policy
});
check("success relative path is safe", /^media\/generated\/video_[a-f0-9]{24}\.mp4$/.test(success.relativePath), true);
check("success filename generated", /^video_[a-f0-9]{24}\.mp4$/.test(success.fileName), true);
check("success MIME fixed", success.mimeType, "video/mp4");
check("success byte count", success.sizeBytes, valid.length);
check("success checksum", success.checksum, `sha256:${createHash("sha256").update(valid).digest("hex")}`);
check("success file committed", existsSync(path.join(successRoot, ...success.relativePath.split("/"))), true);
check("success leaves no part", listParts(successRoot), []);
const successBlob = JSON.stringify(success);
check("metadata has no provider URL", /https?:|signature|url/i.test(successBlob), false);
check("metadata has no absolute path", /[A-Za-z]:\\|\/tmp\//.test(successBlob), false);
check("metadata exact allowlist", Object.keys(success).sort(), ["checksum", "fileName", "mimeType", "relativePath", "sizeBytes"]);

const chunked = await download("/chunked", "chunked");
check("chunked body imported", chunked.sizeBytes, valid.length);
const redirected = await download("/redirect", "redirect");
check("approved redirect imported", redirected.sizeBytes, valid.length);
check("redirect requested target once", fake.requests.filter((r) => r.path === "/redirect").length >= 1 && fake.requests.filter((r) => r.path === "/video").length >= 2, true);

// The transport is injectable: this path uses an owned Node Readable and makes no
// socket request. It also proves the downloader never supplies ambient credentials.
const injectedRoot = root("injected-readable");
let injectedRequest;
const injected = await downloadAndImportVideo({
  source: fake.url("/not-requested?opaque=redacted"), outputRoot: injectedRoot,
  relativeDirectory: "media/generated", generationAttemptId: generateId("attempt"),
  originPolicy: policy,
  fetchImpl: async (_target, init) => {
    injectedRequest = init;
    return { status: 200, headers: new Headers({ "content-type": "video/mp4" }), body: Readable.from([valid.subarray(0, 777), valid.subarray(777)]) };
  }
});
check("injected Readable imported", injected.sizeBytes, valid.length);
check("injected request omits credentials", injectedRequest.credentials, "omit");
check("injected request has no authorization", Object.keys(injectedRequest.headers).some((key) => /authorization|cookie/i.test(key)), false);
check("injected path made no HTTP request", fake.requests.some((r) => r.path === "/not-requested"), false);

// Once the no-overwrite hard link is published, private-link cleanup is best
// effort: a cleanup failure must not misreport a committed artifact as failed.
const cleanupFailureRoot = root("post-commit-cleanup");
const cleanupFailure = await downloadAndImportVideo({
  source: fake.url("/video"), outputRoot: cleanupFailureRoot,
  relativeDirectory: "media/generated", generationAttemptId: generateId("attempt"),
  originPolicy: policy,
  unlinkImpl: async () => { throw new Error("synthetic private-link cleanup failure"); }
});
check("post-commit cleanup failure still returns metadata", cleanupFailure.mimeType, "video/mp4");
check("post-commit cleanup failure keeps committed artifact", existsSync(path.join(cleanupFailureRoot, ...cleanupFailure.relativePath.split("/"))), true);
check("post-commit cleanup failure leaves no part after fallback", listParts(cleanupFailureRoot), []);

// ---- failure cleanup and redaction ----
async function failureLeavesNoPart(name, pathname, code, overrides = {}) {
  const out = root(name);
  let caught;
  try {
    await downloadAndImportVideo({
      source: fake.url(pathname), outputRoot: out, relativeDirectory: "media/generated",
      generationAttemptId: generateId("attempt"), originPolicy: policy, ...overrides
    });
  } catch (err) { caught = err; }
  check(`${name} code`, caught?.code, code);
  check(`${name} leaves no part`, listParts(out), []);
  check(`${name} error redacted`, /https?:|127\.0\.0\.1|signature|[A-Za-z]:\\|\/tmp\//.test(JSON.stringify({ code: caught?.code, message: caught?.message })), false);
}

await failureLeavesNoPart("html-type", "/html", VIDEO_IMPORT_ERRORS.E_MEDIA_INVALID);
await failureLeavesNoPart("html-content", "/html-as-binary", VIDEO_IMPORT_ERRORS.E_MEDIA_INVALID);
await failureLeavesNoPart("malformed", "/malformed", VIDEO_IMPORT_ERRORS.E_MEDIA_INVALID);
await failureLeavesNoPart("too-small", "/short", VIDEO_IMPORT_ERRORS.E_MEDIA_TOO_SMALL);
await failureLeavesNoPart("advertised-large", "/advertised-oversize", VIDEO_IMPORT_ERRORS.E_MEDIA_TOO_LARGE);
await failureLeavesNoPart("stream-large", "/stream-oversize", VIDEO_IMPORT_ERRORS.E_MEDIA_TOO_LARGE, { minBytes: 1024, maxBytes: 32 * 1024 });
await failureLeavesNoPart("status", "/status?signature=never-log", VIDEO_IMPORT_ERRORS.E_MEDIA_HTTP_FAILED);
await failureLeavesNoPart("redirect-limit", "/redirect-loop", VIDEO_IMPORT_ERRORS.E_MEDIA_REDIRECT_LIMIT, { maxRedirects: 1 });
await failureLeavesNoPart("redirect-host", "/redirect-other-host", VIDEO_IMPORT_ERRORS.E_MEDIA_SOURCE_REJECTED);
await failureLeavesNoPart("timeout", "/slow", VIDEO_IMPORT_ERRORS.E_MEDIA_TIMEOUT, { timeoutMs: 100 });

const abortedRoot = root("aborted");
const controller = new AbortController();
const abortPromise = downloadAndImportVideo({
  source: fake.url("/slow"), outputRoot: abortedRoot, relativeDirectory: "media/generated",
  generationAttemptId: generateId("attempt"), originPolicy: policy, signal: controller.signal
});
setTimeout(() => controller.abort(), 20).unref?.();
await throwsCode("external abort rejected", async () => abortPromise, VIDEO_IMPORT_ERRORS.E_MEDIA_ABORTED);
check("external abort leaves no part", listParts(abortedRoot), []);

await throwsCode("relative destination traversal rejected", async () => download("/video", "traversal", { relativeDirectory: "../escape" }), VIDEO_IMPORT_ERRORS.E_MEDIA_CONFIG);
await throwsCode("invalid attempt id rejected", async () => download("/video", "bad-attempt", { generationAttemptId: "attempt_bad" }), VIDEO_IMPORT_ERRORS.E_MEDIA_CONFIG);
await throwsCode("relative output root rejected", async () => download("/video", "bad-root", { outputRoot: "relative/output" }), VIDEO_IMPORT_ERRORS.E_MEDIA_CONFIG);
await throwsCode("invalid timeout rejected", async () => download("/video", "bad-timeout", { timeoutMs: 20 }), VIDEO_IMPORT_ERRORS.E_MEDIA_CONFIG);
await throwsCode("invalid redirect limit rejected", async () => download("/video", "bad-redirect", { maxRedirects: 6 }), VIDEO_IMPORT_ERRORS.E_MEDIA_CONFIG);

// Existing committed artifact must never be overwritten.
const existingRoot = root("existing");
const attempt = generateId("attempt");
const first = await downloadAndImportVideo({
  source: fake.url("/video"), outputRoot: existingRoot, relativeDirectory: "media/generated",
  generationAttemptId: attempt, originPolicy: policy
});
const existingPath = path.join(existingRoot, ...first.relativePath.split("/"));
const before = readFileSync(existingPath);
await throwsCode("existing destination rejected", async () => downloadAndImportVideo({
  source: fake.url("/video"), outputRoot: existingRoot, relativeDirectory: "media/generated",
  generationAttemptId: attempt, originPolicy: policy
}), VIDEO_IMPORT_ERRORS.E_MEDIA_DEST_EXISTS);
check("existing destination bytes preserved", readFileSync(existingPath).equals(before), true);
check("existing destination leaves no part", listParts(existingRoot), []);

await fake.close();
cleanupRoots();

if (failed > 0) {
  console.error(`\n${passed} passed, ${failed} failed`);
  process.exit(1);
}
console.log(`${passed} passed, 0 failed`);
